@push('scripts')<script nonce="{{ $cspNonce }}">(()=>{const form=document.getElementById('image-generation-form'),button=document.getElementById('image-generation-button'),status=document.getElementById('image-generation-status'),image=document.getElementById('generated-image');form.addEventListener('submit',async(event)=>{event.preventDefault();button.disabled=true;status.textContent='Generating securely…';image.classList.add('d-none');try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});const data=await response.json().catch(()=>({message:'The server returned an invalid response.'}));if(!response.ok||data.status!=='success')throw new Error(data.message||'Image generation failed.');image.src=String(data.image_local_path);image.classList.remove('d-none');status.textContent=String(data.message||'Image saved.');}catch(error){status.textContent=error instanceof Error?error.message:'Image generation failed.';}finally{button.disabled=false;}});})();</script>@endpush
